/**
 * Blocked Users API 测试
 */

import { SynapseEnhancedClient } from "../index.ts";
import { loadTestConfig } from "./config.ts";
import { logger } from "../../logger.ts";

const log = logger.getChild("enhanced:test:blocked-users-api");

interface TestResult {
    name: string;
    passed: boolean;
    responseTime: number;
    error?: string;
    response?: any;
}

export class BlockedUsersApiTests {
    private client: SynapseEnhancedClient;
    private config: ReturnType<typeof loadTestConfig>;

    public constructor() {
        this.config = loadTestConfig();
        this.client = new SynapseEnhancedClient({
            baseUrl: this.config.server.baseUrl,
            accessToken: this.config.server.accessToken,
            apiPrefix: this.config.server.apiPrefix,
            timeout: this.config.test.timeout,
        });
    }

    public async runAllTests(): Promise<TestResult[]> {
        log.info("");
        log.info("=============================");
        log.info("Running Blocked Users API Tests...");
        log.info("=============================");

        const results: TestResult[] = [];

        results.push(await this.testGetBlockedUsers());
        results.push(await this.testIsBlocked());
        results.push(await this.testBlockUser());
        results.push(await this.testUnblockUser());

        this.printResults(results);
        return results;
    }

    private printResults(results: TestResult[]): void {
        for (const result of results) {
            const icon = result.passed ? "✓" : "✗";
            log.info(`${icon} ${result.name}: ${result.passed ? "PASSED" : "FAILED"} (${result.responseTime}ms)`);
            if (result.error) {
                log.error(`  Error: ${result.error}`);
            }
        }
        const passed = results.filter((r) => r.passed).length;
        log.info("");
        log.info(`Blocked Users API Results: ${passed}/${results.length} passed`);
    }

    private async testGetBlockedUsers(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const blockedUsers = await this.client.friends.getBlockedUsers();

            return {
                name: "Get Blocked Users",
                passed: Array.isArray(blockedUsers),
                responseTime: Date.now() - startTime,
                response: { count: blockedUsers.length },
            };
        } catch (error: any) {
            return {
                name: "Get Blocked Users",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testIsBlocked(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const isBlocked = await this.client.friends.isBlocked("@test:example.com");

            return {
                name: "Is Blocked",
                passed: typeof isBlocked === "boolean",
                responseTime: Date.now() - startTime,
                response: { isBlocked },
            };
        } catch (error: any) {
            return {
                name: "Is Blocked",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testBlockUser(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const result = await this.client.friends.blockUser("@test:example.com", "Test reason");

            return {
                name: "Block User",
                passed: typeof result === "boolean",
                responseTime: Date.now() - startTime,
                response: { success: result },
            };
        } catch (error: any) {
            return {
                name: "Block User",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testUnblockUser(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const result = await this.client.friends.unblockUser("@test:example.com");

            return {
                name: "Unblock User",
                passed: typeof result === "boolean",
                responseTime: Date.now() - startTime,
                response: { success: result },
            };
        } catch (error: any) {
            return {
                name: "Unblock User",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }
}

const tests = new BlockedUsersApiTests();
tests.runAllTests().catch((error) => log.error(error));
